// Los testers de una prueba cerrada: cuándo se sumaron y, si se fueron, cuándo.
const DIA = 24 * 3600 * 1000;
const f = (s) => Date.parse(s + "T00:00:00Z");
const testers = [
  { n: "T01", alta: "2026-11-20" }, { n: "T02", alta: "2026-11-20" },
  { n: "T03", alta: "2026-11-20" }, { n: "T04", alta: "2026-11-21" },
  { n: "T05", alta: "2026-11-21" }, { n: "T06", alta: "2026-11-21" },
  { n: "T07", alta: "2026-11-22" }, { n: "T08", alta: "2026-11-22" },
  { n: "T09", alta: "2026-11-22", baja: "2026-11-30" },
  { n: "T10", alta: "2026-11-23" }, { n: "T11", alta: "2026-11-23" },
  { n: "T12", alta: "2026-11-23" }, { n: "T13", alta: "2026-11-25" },
];
// Días corridos suscripto hasta "hoy" (sin bajas); con baja, no cuenta.
function diasContinuos(t, hoy) {
  if (t.baja && f(t.baja) <= f(hoy)) return 0;
  return Math.floor((f(hoy) - f(t.alta)) / DIA);
}
function estado(hoy) {
  const ok = testers.filter((t) => diasContinuos(t, hoy) >= 14);
  return ok.length;
}
for (const hoy of ["2026-12-03", "2026-12-04", "2026-12-07", "2026-12-09"]) {
  console.log(hoy, "→ testers con 14 días seguidos:", estado(hoy), estado(hoy) >= 12 ? "(alcanza)" : "(falta)");
}
// ¿Cuándo se llega a 12?
let d = f("2026-11-20");
while (estado(new Date(d).toISOString().slice(0, 10)) < 12) d += DIA;
const llega = new Date(d).toISOString().slice(0, 10);
console.log("Primer día con 12:", llega);
// Hacia atrás desde el lanzamiento deseado (18-12): 7 días de revisión + 14 de prueba
const lanz = f("2026-12-18");
console.log("Empezar la prueba a más tardar el:", new Date(lanz - 21 * DIA).toISOString().slice(0, 10));
